export const q=<T extends Element>(selector:string,root:ParentNode=document):T=>{const element=root.querySelector<T>(selector);if(!element)throw new Error(`Missing ${selector}`);return element;};
export const svg=<K extends keyof SVGElementTagNameMap>(tag:K):SVGElementTagNameMap[K]=>document.createElementNS("http://www.w3.org/2000/svg",tag);
export const button=(text:string,action:()=>void):HTMLButtonElement=>{const control=document.createElement("button");control.type="button";control.textContent=text;control.addEventListener("click",action);return control;};
export const entityName=(entities:readonly {id:string;name:string}[],id:unknown,fallback="Unknown"):string=>entities.find((entity)=>entity.id===id)?.name??fallback;
export const elementByData=<T extends HTMLElement|SVGElement>(attribute:string,id:string):T|undefined=>Array.from(document.querySelectorAll<T>(`[${attribute}]`)).find((element)=>element.getAttribute(attribute)===id);
