export function flowEdgeGeometry(source:{x:number;y:number},target:{x:number;y:number},sourceSize:{width:number;height:number}={width:nodeWidth,height:nodeHeight},targetSize:{width:number;height:number}=sourceSize,sourcePort:FlowPortSide="right",targetPort:FlowPortSide="left"):{startX:number;startY:number;endX:number;endY:number;arrow:string}{const start=flowPortPoint(source,sourceSize,sourcePort),end=flowPortPoint(target,targetSize,targetPort),startX=start.x,startY=start.y,endX=end.x,endY=end.y,dx=endX-startX,dy=endY-startY,length=Math.hypot(dx,dy),unitX=length<0.001?1:dx/length,unitY=length<0.001?0:dy/length,baseX=endX-unitX*12,baseY=endY-unitY*12,normalX=-unitY*7,normalY=unitX*7;return{startX,startY,endX,endY,arrow:`${baseX+normalX},${baseY+normalY} ${endX},${endY} ${baseX-normalX},${baseY-normalY}`};}
